import math
borings = {
    "B-1": (150, 760, 88, 90), "B-2": (420, 620, 92, 120), "B-3": (620, 520, 131, 150),
    "B-4": (900, 650, 104, 120), "B-5": (1000, 300, 97, 120), "B-6": (300, 1000, 85, 90),
    "B-7": (640, 1080, 69, 90), "B-8": (1250, 1000, 99, 120), "B-9": (1500, 250, 112, 120),
    "B-10": (1750, 700, 64, 90), "B-11": (1450, 1200, 90, 90), "B-12": (400, 200, 101, 120),
}
